using System;
using System.Text;

class Program
{
    static string Slow(int n)
    {
        string s = "";
        for (int i = 0; i < n; i++) s += i + ",";   // n new strings
        return s;
    }

    static string Fast(int n)
    {
        var sb = new StringBuilder(n * 4);
        for (int i = 0; i < n; i++) sb.Append(i).Append(',');
        return sb.ToString();                          // one final string
    }

    static void Main()
    {
        Console.WriteLine(Slow(5)); // 0,1,2,3,4,
        Console.WriteLine(Fast(5) == Slow(5)); // True
    }
}

static void Swap(ref int a, ref int b) { int t = a; a = b; b = t; }
static int Divide(int a, int b, out int remainder) { remainder = a % b; return a / b; }
static int Sum(params int[] values) { int s = 0; foreach (int v in values) s += v; return s; }

int x = 1, y = 2;
Swap(ref x, ref y);
Console.WriteLine(x + " " + y);
int q = Divide(17, 5, out int r);
Console.WriteLine(q + " r " + r);
Console.WriteLine(Sum(1, 2, 3, 4));

