using System;
using System.Text;

class Program
{
    static bool TryCompress(string input, out string compressed)
    {
        var sb = new StringBuilder(input.Length);
        int i = 0;
        while (i < input.Length)
        {
            char c = input[i];
            int j = i;
            while (j < input.Length && input[j] == c) j++;
            sb.Append(c).Append(j - i);
            i = j;
        }
        compressed = sb.ToString();
        if (compressed.Length < input.Length) return true;
        compressed = input;
        return false;
    }

    static void Main()
    {
        string[] lines = Console.In.ReadToEnd().Replace("\r", "").Split('\n');
        int n = int.Parse(lines[0].Trim());
        for (int i = 1; i <= n; i++)
        {
            string s = lines[i].Trim();
            string result;
            if (TryCompress(s, out result))
                Console.WriteLine(result + " (saved " + (s.Length - result.Length) + ")");
            else
                Console.WriteLine(result + " (unchanged)");
        }
    }
}
